export const FinalizeUploadParams = zod.object({
  "upload_id": zod.coerce.string().uuid()
})

export const finalizeUploadBodyContentMax = 5242880;

export const finalizeUploadBodyContentHashRegExp = new RegExp('^[a-fA-F0-9]{64}$');
export const finalizeUploadBodySealedObjectPathRegExp = new RegExp('^/objects/sealed/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$');
export const finalizeUploadBodySourceMax = 2000;

export const finalizeUploadBodySourceUrlRegExp = new RegExp('^https?:/');
export const finalizeUploadBodyNotesMax = 20000;

export const finalizeUploadBodyEntitiesItemValueMax = 2000;

export const finalizeUploadBodyEntitiesMax = 1000;



export const FinalizeUploadBody = zod.object({
  "content": zod.string().max(finalizeUploadBodyContentMax),
  "content_hash": zod.string().regex(finalizeUploadBodyContentHashRegExp),
  "sealed_object_path": zod.string().regex(finalizeUploadBodySealedObjectPathRegExp),
  "source": zod.string().min(1).max(finalizeUploadBodySourceMax),
  "source_url": zod.string().url().regex(finalizeUploadBodySourceUrlRegExp).nullish(),
  "collected_at": zod.coerce.date().nullish(),
  "reliability": zod.enum(['A', 'B', 'C', 'D', 'E', 'F', 'UNKNOWN', 'LOW', 'MEDIUM', 'HIGH', 'VERIFIED']),
  "notes": zod.string().max(finalizeUploadBodyNotesMax).optional(),
  "entities": zod.array(zod.object({
  "type": zod.enum(['ACTOR_HYPOTHESIS', 'PERSONA', 'USERNAME', 'EMAIL', 'PGP_KEY', 'CRYPTO_WALLET', 'DOMAIN', 'IP_ADDRESS', 'ONION_SERVICE', 'URL', 'POST', 'MESSAGE', 'DOCUMENT', 'MARKETPLACE', 'FORUM', 'ORGANIZATION', 'INFRASTRUCTURE', 'FILE_HASH', 'CRYPTO_TRANSACTION', 'LOCATION_INDICATOR', 'DEVICE_INDICATOR']),
  "value": zod.string().min(1).max(finalizeUploadBodyEntitiesItemValueMax)
})).max(finalizeUploadBodyEntitiesMax).optional()
})

export const FinalizeUploadResponse = zod.object({
  "id": zod.string().uuid(),
  "case_id": zod.string().uuid(),
  "type": zod.enum(['MANUAL', 'DOCUMENT', 'PUBLIC_SOURCE', 'DATASET', 'API_IMPORT', 'SCREENSHOT_METADATA', 'TEXT', 'CRYPTO_DATA', 'INFRASTRUCTURE_DATA']),
  "source": zod.string(),
  "source_url": zod.string().url().nullish(),
  "collected_at": zod.coerce.date(),
  "collector_id": zod.string().uuid(),
  "content_hash": zod.string(),
  "notes": zod.string(),
  "reliability": zod.enum(['A', 'B', 'C', 'D', 'E', 'F', 'UNKNOWN', 'LOW', 'MEDIUM', 'HIGH', 'VERIFIED']),
  "entity_ids": zod.array(zod.string().uuid()),
  "object_path": zod.string().nullish(),
  "content": zod.string().nullish(),
  "created_at": zod.coerce.date()
})


